373: function generatePlatforms() {
374:   const bw = arena.right - arena.left;
375:   const mirror = Math.random() < 0.5;
376:   const w = [
377:     clamp(250 * S, bw * 0.22, bw * 0.34),
378:     clamp(215 * S, bw * 0.20, bw * 0.30),
379:     clamp(185 * S, bw * 0.17, bw * 0.26),
380:   ];
381: 
382:   // Keep the lowest ledge above a brawler's head (plus badge) and keep every
383:   // step within a single jump. Short/landscape screens get fewer ledges rather
384:   // than a cramped stack that clips through the fighters.
385:   const step = 125 * S;
386:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
387:   let levels = 1;
388:   if (maxRise >= step * 2) levels = 2;
389:   if (maxRise >= step * 3) levels = 3;
390: 
391:   // Chain the platforms horizontally so each one overlaps the next.
392:   const xs = [arena.left + bw * 0.05];
393:   for (let i = 1; i < levels; i++) {
394:     xs[i] = Math.min(xs[i - 1] + w[i - 1] - w[i] * 0.34, arena.right - w[i] - 10);
395:   }
396: 
397:   platforms = [];
398:   for (let i = 0; i < levels; i++) {
399:     platforms.push({
400:       x: xs[i],
401:       y: floorY - step * (i + 1),
402:       w: w[i],
403:       h: 18 * S,
404:       style: i,
405:     });
406:   }
407: 
408:   if (mirror) {
409:     for (const p of platforms) p.x = arena.left + (arena.right - p.x - p.w);
410:   }
411:   for (const p of platforms) {
412:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
