function throwPlan(p, charge) {
  const h = handPoint(p);
  const t = aimTarget(p);
  const dx = t.x - h.x, dy = t.y - h.y;
  let T = clamp(Math.hypot(dx, dy) / (1080 * S), 0.34, 0.76) * (1 - 0.16 * charge);
  const tx = t.x;
  const ty = t.y;
  const g = ballGravityFor();
  const vx = (tx - h.x) / T;
  const vy = (ty - h.y - 0.5 * g * T * T) / T;
  return { vx, vy, T, g, hand: h, tx, ty };
}

