const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ ...require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright').devices['iPhone 12'], hasTouch: true });
  const page = await ctx.newPage();
  await page.goto('http://localhost:3002');
  await page.waitForTimeout(500);
  await page.evaluate(() => { window.__bonk.start('2p'); window.__bonk.play(); });
  await page.waitForTimeout(400);
  const btn = await page.locator('#touch .pad.p1 .tbtn.jump');
  const box = await btn.boundingBox();
  console.log('jump box', box);
  await page.touchscreen.tap(box.x + box.width/2, box.y + box.height/2);
  await page.waitForTimeout(300);
  const y = await page.evaluate(() => window.__bonk.info().players[0].y);
  console.log('player0 y after tap', y);
  // joystick drag
  const joy = await page.locator('#touch .pad.p1 .joystick .stick-base');
  const jb = await joy.boundingBox();
  const cx = jb.x + jb.width/2, cy = jb.y + jb.height/2;
  await page.touchscreen.tap(cx, cy);
  await page.waitForTimeout(200);
  // drag right
  await page.touchscreen.touchStart(cx, cy);
  await page.waitForTimeout(50);
  await page.touchscreen.touchMove(cx + 60, cy);
  await page.waitForTimeout(400);
  const x = await page.evaluate(() => window.__bonk.info().players[0].x);
  console.log('player0 x after drag', x);
  await page.touchscreen.touchEnd();
  await browser.close();
})();

